const D = { coverage: .5, scale: 1, energy: .6, density: .5, hue: 45, speed: 1, x: .3, y: .42, alpha: .62, style: 'gold', act: 'lay', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:v>b?b:v, md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2rgb=(h,s,b)=>{ h=md(h,360)/60; s=cl(s,0,100)/100; b=cl(b,0,100)/100;
  const c=b*s, x=c*(1-Math.abs((h%2)-1)), m=b-c; let r,g,l;
  if(h<1){r=c;g=x;l=0;} else if(h<2){r=x;g=c;l=0;} else if(h<3){r=0;g=c;l=x;}
  else if(h<4){r=0;g=x;l=c;} else if(h<5){r=x;g=0;l=c;} else {r=c;g=0;l=x;}
  return [(r+m)*255,(g+m)*255,(l+m)*255]; };
const rgba=(c,a)=>'rgba('+(c[0]|0)+','+(c[1]|0)+','+(c[2]|0)+','+a.toFixed(4)+')';
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style, act=P.act;
const cov=cl(P.coverage,0,1), sc=cl(P.scale,.5,2.2), al=cl(P.alpha,0,1);
const dens=cl(P.density,0,1), spd=cl(P.speed,.1,4), en=cl(P.energy,0,1);
const H=md(P.hue,360), T=K.t*spd;
const TD=K.t*(.45+.55*Math.min(spd,3));
if(al<=0.002) { blendMode(BLEND); }
else {

S.bass=(S.bass||0)*.86+(A.bass||0)*.14;
S.tre=(S.tre||0)*.86+(A.treble||0)*.14;

// ---- dramaturgy ----
const sec=((K.section|0)%8+8)%8;
let burnK, shed, layRate;
if(act==='burnish'){ burnK=2.1; shed=0; layRate=.45; }
else if(act==='shed'){ burnK=.7; shed=.35+.45*(.5+.5*Math.sin(sec*.85+T*.019)); layRate=1.5; }
else { burnK=1; shed=.06; layRate=1; }

// ---- the agate burnisher travels across the gilding on a monotonic orbit: leaves ignite
// in sequence as it passes. This is the motion floor and it cannot re-phase away.
const bAng=.089*TD*burnK, bAng2=.211*TD*burnK+1.9;
const bx=W*(cl(P.x,0,1)+.30*Math.cos(bAng)+.11*Math.cos(bAng2));
const by=Hh*(cl(P.y,0,1)+.26*Math.sin(bAng)+.10*Math.sin(bAng2));
const bR=u*(.30+.22*dens);
const lAz=bAng*.7+.9;
const lxd=Math.cos(lAz), lyd=Math.sin(lAz);

// ---- style ----
let GOLD, HIGH, BOLE, setout=0, matte=1;
if(sty==='moon_gold'){ GOLD=hsb2rgb(H+12,17,84); HIGH=hsb2rgb(H+14,7,99); BOLE=hsb2rgb(H+186,30,30); }
else if(sty==='copper'){ GOLD=hsb2rgb(H-24,62,63); HIGH=hsb2rgb(H-12,40,93); BOLE=hsb2rgb(H+150,34,26); }
else if(sty==='graphite'){ GOLD=hsb2rgb(H+180,7,42); HIGH=hsb2rgb(H+180,4,74); BOLE=hsb2rgb(H+178,10,16); matte=.45; }
else if(sty==='setout'){ GOLD=hsb2rgb(H,34,72); HIGH=hsb2rgb(H+6,16,97); BOLE=hsb2rgb(H+170,30,30); setout=1; }
else { GOLD=hsb2rgb(H,54,74); HIGH=hsb2rgb(H+8,26,99); BOLE=hsb2rgb(H-32,58,34); }

// ---- the leaf lattice: gilders lay overlapping squares in courses. `coverage` decides
// which cells actually took — the misses are the holidays that let the scene through.
const leafR=cl(.155*sc,.055,.42)*u;
const step=leafR*1.34;
const cols=Math.ceil(W/step)+2, rows=Math.ceil(Hh/step)+2;
const NV=13;
const lkey=P.seed+'|'+Math.round(leafR)+'|'+cols+'x'+rows;
if(S.lk!==lkey){ S.lk=lkey; const n=Math.min(cols*rows,130);
  const LF=new Float32Array(n*(5+NV)); let m=0;
  for(let r=0;r<rows&&m<n;r++) for(let c=0;c<cols&&m<n;c++){
    const b=m*(5+NV);
    LF[b]=(c-.5)*step+(fr(m*3.1+10)-.5)*step*.34;
    LF[b+1]=(r-.5)*step+(fr(m*3.1+11)-.5)*step*.34;
    LF[b+2]=(fr(m*3.1+12)-.5)*.42;                  // each leaf lands a little off-square
    LF[b+3]=fr(m*3.1+13);                           // did this cell take? (vs coverage)
    LF[b+4]=fr(m*3.1+14);                           // per-leaf tone
    for(let v=0;v<NV;v++) LF[b+5+v]=.80+.30*fr(m*31.7+v*2.3+15);  // torn edge radii
    m++;
  }
  S.lf=LF; S.nl=m; }
const LF=S.lf, NLF=S.nl;

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
noStroke();
const glow=(.35+.9*en)*(.6+.6*K.intensity)+S.tre*.3*en;

for(let m=0;m<NLF;m++){
  const b=m*(5+NV);
  const took=LF[b+3];
  if(took>cov) continue;                             // a holiday — the bole shows through
  // shed: the gilding is failing, leaves lift and go
  const lift=shed>0?cl((fr(m*5.3+40)-(1-shed))*3.2,0,1):0;
  if(lift>=1) continue;
  const cx=LF[b], cy=LF[b+1], ang=LF[b+2];
  // how hard is the burnisher on this leaf right now?
  const dbx=cx-bx, dby=cy-by;
  const burn=Math.exp(-(dbx*dbx+dby*dby)/(bR*bR));
  const tone=(.72+.28*LF[b+4])*(1+.55*Math.exp(-((cx-bx)*(cx-bx)+(cy-by)*(cy-by))/(bR*bR))*burnK*glow);
  const aBase=(setout?.0:(.62+.24*LF[b+4]))*al*(1-lift);
  push();
  translate(cx,cy); rotate(ang+lift*.5);
  // the torn deckle edge of a beaten leaf
  const path=[];
  for(let v=0;v<NV;v++){ const a2=v/NV*TAU, rr=leafR*LF[b+5+v]*(1+lift*.12);
    path.push([Math.cos(a2)*rr*1.02, Math.sin(a2)*rr*.98]); }
  if(setout){
    // non-representational: the gilder's setting-out. Flat tinted planes and hard linework
    // — no modelling, no material, no sheen. The burnisher passing is what lights a course.
    // each course carries its own slow phase, so the plan never sits perfectly still
    const li=cl(.26+.68*burn*burnK*glow+.13*Math.sin(TD*.13+m*1.7)+.07*Math.sin(TD*.31+m*.7),0,1);
    fill(md(H+6,360),26,42+40*li,Math.min(64,(16+30*li)*al*(1-lift)));
    stroke(md(H+6,360),18,97,Math.min(96,(30+60*li)*al*(1-lift)));
    strokeWeight(Math.max(1,u*.0040*(.6+.8*li)));
    beginShape(); for(const p2 of path) vertex(p2[0],p2[1]); endShape(CLOSE);
    // the square the leaf was cut from, drawn under its torn edge
    noFill();
    stroke(md(H+6,360),12,99,Math.min(72,(14+44*li)*al*(1-lift)));
    strokeWeight(Math.max(.8,u*.0022));
    const q=leafR*.62;
    beginShape(); vertex(-q,-q); vertex(q,-q); vertex(q,q); vertex(-q,q); endShape(CLOSE);
    pop(); continue;
  }
  // each leaf carries its own sheen: a gradient running with the light
  const g1=dc.createLinearGradient(-leafR*lxd,-leafR*lyd,leafR*lxd,leafR*lyd);
  const lo=[GOLD[0]*tone*.52,GOLD[1]*tone*.52,GOLD[2]*tone*.55];
  const mid=[GOLD[0]*tone,GOLD[1]*tone,GOLD[2]*tone];
  const hiC=[HIGH[0],HIGH[1],HIGH[2]];
  const hot=cl(burn*burnK*glow*matte,0,1);
  g1.addColorStop(0, rgba(lo, aBase*.94));
  g1.addColorStop(.42, rgba(mid, aBase));
  g1.addColorStop(cl(.60+.22*Math.sin(TD*.09+m),.5,.9), rgba([mid[0]+(hiC[0]-mid[0])*hot, mid[1]+(hiC[1]-mid[1])*hot, mid[2]+(hiC[2]-mid[2])*hot], aBase));
  g1.addColorStop(1, rgba(lo, aBase*.9));
  dc.fillStyle=g1;
  dc.beginPath(); dc.moveTo(path[0][0],path[0][1]);
  for(let v=1;v<NV;v++) dc.lineTo(path[v][0],path[v][1]);
  dc.closePath(); dc.fill();
  // the lap line where this leaf overlaps its neighbour
  dc.strokeStyle=rgba(lo, aBase*.5); dc.lineWidth=Math.max(.5,u*.0011); dc.stroke();
  pop();
}

// ---- skewings: the loose fragments that never stuck, still drifting and tumbling ----
const NSK=Math.round((10+dens*46)*(1+shed*1.6));
dc.globalCompositeOperation='lighter';
for(let k=0;k<NSK;k++){
  const ph=fr(k*2.7+200);
  const fall=md(ph+TD*(.011+.020*fr(k*2.7+201))*(1+shed),1);
  const sx2=md(fr(k*2.7+202)+.06*Math.sin(TD*.21+k*1.7)+TD*.0018*(fr(k*2.7+206)-.5),1)*W;
  const sy2=fall*Hh*1.06-Hh*.03;
  const tum=TD*(.5+1.1*fr(k*2.7+203))+k;
  const sz=u*(.0035+.0075*fr(k*2.7+204))*sc;
  const fo=Math.abs(Math.cos(tum));                  // edge-on flip: a fleck of foil is 2D
  const dsk=Math.exp(-((sx2-bx)*(sx2-bx)+(sy2-by)*(sy2-by))/(bR*bR*2.2));
  const aa=(.18+.55*fo)*(.35+.9*dsk)*al*glow*(setout?.5:1);
  fill(md(H+8*fr(k*2.7+205),360), setout?18:38, 96, Math.min(72,aa*74));
  push(); translate(sx2,sy2); rotate(tum*.6);
  ellipse(0,0,sz*fo*1.9+sz*.18,sz*1.5);
  pop();
}
dc.globalCompositeOperation=oldOp;

blendMode(BLEND); dc.globalAlpha=1; dc.shadowBlur=0; noStroke(); noTint();
}
